-- Eastern Plaguelands: creature abilities
-- Most of the zone's creatures (the Scourge of the Plaguewood and Eastwall, the Scarlet Crusade, the plaguebats, plaguehounds and abominations) had no AI or ran classic rows. Port their abilities from the
-- Cataclysm data, and from the classic data where Cataclysm has none, keeping the quest scripts already in place; gossip and quest
-- reward scripts of the references are left out. The creatures no reference scripts cast their sniffed spells (creature_template
-- spell1-8).

SET @ENTRIES := '1843,1844,8519,8520,8521,8522,8526,8535,8537,8538,8541,8548,8551,8556,8563,8596,8598,9448,9449,9450,9452,10818,10819,10821,10824,10825,10826,10827,11290,11896,11897,12261,16184,16378,28488,31094,31096,45443,45444,45450,45453,45579,45681,45691,45692,45743,45744,45851,45867,45868,45897,46092,46095,46096,46167,47060,48718';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);

-- Creatures without reference data: their sniffed creature_template spell1-8
SET @ENTRIES := '11620,14881,46093,46094,51986';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
